function updateTask(fd){const old=D.tasks.find(t=>t.id===U.edit),edit=!!old,title=String(fd.get('title')||'').trim(),due=jparse(fd.get('dueJ'));if(!title||!due)return toast('عنوان و تاریخ شمسی معتبر وارد کنید.',true);const projectId=String(fd.get('projectId')||''),requested=String(fd.get('assignee')||APP.user.uid),managerPrivate=isProjectControlsManager()&&requested===MANAGER_ID,assignee=managerPrivate?APP.user.uid:requested;if(projectId&&!proj(projectId))return toast('پروژه انتخاب‌شده معتبر نیست.',true);if(!isAdmin()&&(managerPrivate||assignee!==APP.user.uid||!availableProject(projectId)))return toast('شما مجوز انتخاب این مسئول یا پروژه را ندارید.',true);if(assignee!==APP.user.uid&&!person(assignee)?.active)return toast('مسئول باید یک حساب تأییدشده باشد.',true);if(projectId&&assignee!==APP.user.uid&&!person(assignee)?.projects.includes(projectId))return toast('این مسئول به پروژه انتخاب‌شده دسترسی ندارد.',true);if(edit&&!isAdmin()&&(old.createdBy!==APP.user.uid||old.status==='done'))return toast('امکان ویرایش این فعالیت وجود ندارد.',true);const desired=String(fd.get('status')||old?.status||'todo');if(!Object.hasOwn(statuses,desired))return toast('وضعیت نامعتبر است.',true);if(desired==='blocked'&&edit&&isAdmin()&&!String(fd.get('blockReason')||'').trim())return toast('برای وضعیت متوقف، دلیل توقف ضروری است.',true);if(edit){if(isAdmin()&&managerTask(old)&&!managerPrivate&&!confirm('این فعالیت خصوصی با واگذاری به کارمند، برای مسئول جدید قابل مشاهده می‌شود. ادامه می‌دهید؟'))return;Object.assign(old,{title,projectId,assignee,due,priority:String(fd.get('priority')||'normal'),weight:managerPrivate?0:isProjectControlsManager()?(+fd.get('weight')||3):(old.weight??0),visibility:managerPrivate?'manager_private':'team',description:String(fd.get('description')||'').trim(),updatedAt:new Date().toISOString()});if(isAdmin()){if(desired==='blocked'){const reason=String(fd.get('blockReason')||'').trim();old.blockReason=reason;(old.notes||=[]).push({text:'دلیل توقف: '+reason,by:actorName(APP.user.uid),date:isoToday()})}old.status=desired}if(!isAdmin())(old.notes||=[]).push({text:'ویرایش فعالیت توسط '+actorName(APP.user.uid),by:actorName(APP.user.uid),date:isoToday()});record('edit','ویرایش فعالیت'+(fd.get('editReason')?'؛ علت: '+fd.get('editReason'):''),old.id)}else{const t={id:id('t'),title,projectId,assignee,due,priority:String(fd.get('priority')||'normal'),weight:managerPrivate?0:isProjectControlsManager()?(+fd.get('weight')||3):0,visibility:managerPrivate?'manager_private':'team',description:String(fd.get('description')||'').trim(),status:'todo',createdBy:APP.user.uid,createdAt:isoToday(),updatedAt:new Date().toISOString(),notes:[],submittedAt:null,evalId:null};D.tasks.push(t);record('new','فعالیت جدید ثبت شد',t.id)}closeModal();save(edit?'فعالیت ویرایش شد.':'فعالیت ثبت شد.')}
