 const managerPrivate=isProjectControlsManager()&&who===MANAGER_ID;const assigned=managerPrivate?APP.user.uid:who;if(pid&&assigned!==APP.user.uid&&!person(assigned)?.projects.includes(pid))return toast('این مسئول به پروژه انتخاب‌شده دسترسی ندارد.',true);
 const frequency=String(fd.get('frequency')||'weekly');
 if(!Object.hasOwn(freqNames,frequency))return toast('نوع تکرار نامعتبر است.',true);
